import heapq

def match(orders):
    trades = []
    buy_heap = []  # max-heap: (-price, seq, order)
    sell_heap = []  # min-heap: (price, seq, order)
    orders_by_id = {}  # id -> order dict (for cancel/status tracking)
    seq_counter = 0

    def make_order(id_, side, price, qty, seq):
        return {'id': id_, 'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            _, id_ = o
            ordr = orders_by_id.get(id_)
            if ordr is not None and ordr['active'] and ordr['qty'] > 0:
                ordr['active'] = False
            continue

        if typ == 'limit':
            _, id_, side, price, qty = o
        elif typ == 'ioc':
            _, id_, side, price, qty = o
        elif typ == 'market':
            _, id_, side, qty = o
            price = None
        else:
            continue

        seq_counter += 1
        ordr = make_order(id_, side, price, qty, seq_counter)
        orders_by_id[id_] = ordr

        remaining = qty

        if side == 'buy':
            # match against sell_heap
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_ordr = sell_heap[0]
                if not top_ordr['active'] or top_ordr['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if price is not None and top_ordr['price'] > price:
                    break
                trade_qty = min(remaining, top_ordr['qty'])
                trades.append([id_, top_ordr['id'], top_ordr['price'], trade_qty])
                remaining -= trade_qty
                top_ordr['qty'] -= trade_qty
                if top_ordr['qty'] == 0:
                    top_ordr['active'] = False
                    heapq.heappop(sell_heap)
                else:
                    if remaining == 0:
                        break
            ordr['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(buy_heap, (-price, seq_counter, ordr))
            else:
                ordr['active'] = False

        else:  # sell
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_ordr = buy_heap[0]
                if not top_ordr['active'] or top_ordr['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                top_price = -neg_price
                if price is not None and top_price < price:
                    break
                trade_qty = min(remaining, top_ordr['qty'])
                trades.append([top_ordr['id'], id_, top_ordr['price'], trade_qty])
                remaining -= trade_qty
                top_ordr['qty'] -= trade_qty
                if top_ordr['qty'] == 0:
                    top_ordr['active'] = False
                    heapq.heappop(buy_heap)
                else:
                    if remaining == 0:
                        break
            ordr['qty'] = remaining
            if typ == 'limit' and remaining > 0:
                heapq.heappush(sell_heap, (price, seq_counter, ordr))
            else:
                ordr['active'] = False

    return trades

